 def send(self,rows,cameras=[]):
  a=np.asarray(rows); before=self.r.status();
  np.save(f'{OUT}/pending.npy',a)
  try: res=self.r.submit('ee_pose',a,dt=.05,cameras=cameras,video='none')
  except Exception:
   stat=self.r.wait_ready()
   if stat['control_steps']==before['control_steps']: res=self.r.submit('ee_pose',a,dt=.05,cameras=cameras,video='none')
